This is probably not desirable, and I'm not a Next.js master, but would it not be possible to return a different JSX template in the root layout (/app/layout.tsx) for certain route paths?

Something like this:

```js
export default function Layout({ children }) {
  const router = useRouter();

  if (router.pathname.startsWith('/store')) {
    return (
      <Document>
        <h1>Store Root</h1>
        {children}
      </Document>
    );
  }

  if (router.pathname.startsWith('/admin')) {
    return (
      <Document>
        <h1>Admin Root</h1>
        {children}
      </Document>
    );
  }

  if (router.pathname === '/') {
    return (
      <Document>
        <h1>Landing Page Root</h1>
        {children}
      </Document>
    );
  }

  return (
    <Document>
      <h1>Other Pages Root</h1>
      {children}
    </Document>
  );
}

function Document({ children }) {
  return (
    <html>
      <head>
        {/* Head stuff */}
      </head>
      <body>
        {children}
      </body>
    </html>
  );
}
```

